-- Flashcard top-up: Biology|OCR A|gcse — brings each topic up to 30 cards.
-- Generated by scripts/build-flashcard-topup.js from flashcards/topup/src/biology-ocr-a-gcse.txt
-- Safe to re-run: skips fronts already present and never takes a topic past 30.
WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'What is the function of the nucleus?', 'Contains genetic material (DNA as chromosomes) that controls the cell''s activities by coding for proteins.', 1),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'What is the function of the cell membrane?', 'Controls what enters and leaves the cell; it is partially permeable.', 2),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'What is the function of the mitochondria?', 'Site of aerobic respiration, releasing energy for the cell.', 3),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'What is the function of ribosomes?', 'Site of protein synthesis, where amino acids are joined in the order coded by mRNA.', 4),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'What is the function of the cytoplasm?', 'Jelly-like fluid where many chemical reactions take place, controlled by enzymes.', 5),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'What is the function of the chloroplast?', 'Absorbs light energy for photosynthesis; contains the green pigment chlorophyll.', 6),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'What is the function of the plant cell wall?', 'Made of cellulose; strengthens the cell and supports the plant, preventing it bursting when turgid.', 7),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'What is the function of the permanent vacuole?', 'Contains cell sap; keeps the cell turgid to support the plant.', 8),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'Name three structures found in plant cells but not animal cells.', 'Cellulose cell wall, chloroplasts and a permanent vacuole.', 9),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'How does a prokaryotic cell differ from a eukaryotic cell?', 'Prokaryotes have no nucleus (DNA is a single circular chromosome free in the cytoplasm), no membrane-bound organelles, and are much smaller.', 10),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'What are plasmids?', 'Small rings of DNA found in prokaryotes, often carrying genes such as antibiotic resistance.', 11),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'Give two structures found in a bacterial cell.', 'Any two: cell wall, cell membrane, cytoplasm, ribosomes, circular chromosomal DNA, plasmids (sometimes a flagellum).', 12),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'Calculate the magnification if image size is 12 mm and real size is 0.04 mm.', 'Magnification = image ÷ real = 12 ÷ 0.04 = ×300.', 13),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'State the magnification equation.', 'Magnification = image size ÷ real (actual) size. Both must be in the same units.', 14),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'A cell is 50 µm long and drawn at ×400. How long is the drawing?', 'Image = real × magnification = 50 × 400 = 20 000 µm = 20 mm.', 15),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'How many micrometres are in a millimetre?', '1 mm = 1000 µm (and 1 µm = 1000 nm).', 16),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'Calculate total magnification with a ×10 eyepiece and ×40 objective.', 'Total magnification = eyepiece × objective = 10 × 40 = ×400.', 17),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'What is resolution?', 'The ability to distinguish between two points that are close together; higher resolution gives more detail.', 18),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'Why does an electron microscope show more detail than a light microscope?', 'Electrons have a much shorter wavelength than light, giving much higher resolution and magnification, so organelles like ribosomes can be seen.', 19),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'Give one disadvantage of electron microscopes.', 'Expensive and large; specimens must be dead and in a vacuum; preparation is complex; images are black and white.', 20),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'Why are stains used in light microscopy?', 'To increase contrast so colourless structures (e.g. nucleus) become visible; e.g. iodine for plant cells, methylene blue for animal cells.', 21),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'PAG B1: How do you prepare an onion epidermis slide?', 'Peel a thin layer with forceps, lay flat on slide, add iodine stain, lower coverslip at an angle with a mounted needle to avoid air bubbles.', 22),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'Why must the specimen be thin when viewed under a light microscope?', 'So light can pass through it and the cells are in a single layer, allowing structures to be seen clearly.', 23),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'PAG B1: How should you focus a light microscope?', 'Start on lowest power; use coarse focus while watching from the side, then focus away from the slide; switch to higher power and use only the fine focus.', 24),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'Why should the coverslip be lowered at an angle?', 'To prevent air bubbles being trapped, which would obscure the cells.', 25),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'What are the rules for a scientific drawing of cells?', 'Pencil, clear continuous lines, no shading, label lines with a ruler not crossing, include title and magnification or scale bar.', 26),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'What is the difference between magnification and resolution?', 'Magnification is how many times larger the image is; resolution is the level of detail (smallest separation that can be distinguished).', 27),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'Why can bacteria not be seen in detail with a light microscope?', 'They are very small (about 1–5 µm) and their internal structures are below the resolving power of light microscopes.', 28),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'Write 0.000 005 m in standard form and in micrometres.', '5 × 10⁻⁶ m = 5 µm.', 29),
  ('Biology', 'OCR A', 'gcse', 'B1.1', 'Cell Structures', 'Exam trap: does a plant root hair cell have chloroplasts?', 'No. Root cells are underground and receive no light, so they lack chloroplasts even though they are plant cells.', 30),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'What is DNA?', 'A polymer made of two strands of nucleotides twisted into a double helix, carrying the genetic code.', 1),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'What is a nucleotide made of?', 'A phosphate group, a deoxyribose sugar and one of four bases (A, T, C, G).', 2),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'Which DNA bases pair together?', 'Adenine with thymine (A–T) and cytosine with guanine (C–G); complementary base pairing via weak hydrogen bonds.', 3),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'What is a gene?', 'A section of DNA that codes for a specific protein.', 4),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'How many bases code for one amino acid?', 'Three bases (a triplet or codon) code for one amino acid.', 5),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'What is the genome?', 'The entire genetic material of an organism.', 6),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', '(Higher) What happens during transcription?', '(Higher) In the nucleus, DNA unzips and a complementary mRNA copy of the gene''s template strand is made.', 7),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', '(Higher) What happens during translation?', '(Higher) At ribosomes, mRNA codons are read and tRNA brings matching amino acids, which are joined into a polypeptide chain.', 8),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', '(Higher) Why is mRNA needed in protein synthesis?', '(Higher) DNA is too large to leave the nucleus; mRNA carries a copy of the gene to the ribosomes in the cytoplasm.', 9),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'How does a polypeptide become a functional protein?', 'The amino acid chain folds into a specific 3D shape that determines its function, e.g. an enzyme''s active site.', 10),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'PAG B2: How do you extract DNA from fruit?', 'Mash fruit with detergent and salt, filter, add ice-cold ethanol; DNA precipitates as white strands at the boundary.', 11),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'What is an enzyme?', 'A protein that acts as a biological catalyst, speeding up reactions without being used up.', 12),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'What is the active site?', 'The region of an enzyme with a specific shape that the substrate binds to.', 13),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'Describe the lock and key model.', 'The substrate has a complementary shape to the active site, forming an enzyme–substrate complex; products are released and the enzyme is unchanged.', 14),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'Why are enzymes specific?', 'Only a substrate with a shape complementary to the active site can bind.', 15),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'What does denatured mean for an enzyme?', 'The active site has permanently changed shape (bonds broken by high temperature or extreme pH), so the substrate no longer fits.', 16),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'Describe the effect of temperature on enzyme activity.', 'Rate rises with temperature (more kinetic energy, more collisions) up to the optimum (about 37 °C in humans), then falls sharply as the enzyme denatures.', 17),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'Describe the effect of pH on enzyme activity.', 'Each enzyme has an optimum pH; either side, the active site shape changes, reducing activity until it is denatured.', 18),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'Describe the effect of substrate concentration on enzyme activity.', 'Rate increases as more collisions occur until all active sites are occupied; then rate plateaus as enzyme concentration is limiting.', 19),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'Exam trap: do enzymes die at high temperature?', 'No. Enzymes are not alive; say they are denatured because the active site changes shape.', 20),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'What does amylase break down?', 'Starch into maltose (a sugar).', 21),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'What do proteases break down?', 'Proteins into amino acids.', 22),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'What do lipases break down?', 'Lipids (fats) into fatty acids and glycerol.', 23),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'What do carbohydrases break down?', 'Carbohydrates (e.g. starch) into simple sugars.', 24),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'PAG B4: How can you investigate the effect of pH on amylase?', 'Mix amylase, starch and buffer at a set pH in a water bath; sample every 30 s onto iodine in a spotting tile; time until iodine stays orange.', 25),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'PAG B4: State the variables in the amylase pH investigation.', 'IV: pH (buffer). DV: time for starch to disappear. Controls: temperature, volume and concentration of amylase and starch.', 26),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'How do you calculate rate of reaction from a time?', 'Rate = 1 ÷ time (or amount changed ÷ time). E.g. 1 ÷ 50 s = 0.02 s⁻¹.', 27),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'Calculate the rate if 30 cm³ of oxygen is produced in 60 s.', 'Rate = 30 ÷ 60 = 0.5 cm³/s.', 28),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'Why is a water bath used in enzyme practicals?', 'To keep temperature constant so it is a controlled variable (or to set the independent variable).', 29),
  ('Biology', 'OCR A', 'gcse', 'B1.2', 'What Happens in Cells', 'What is the role of enzymes in synthesis reactions?', 'They join small molecules into larger ones, e.g. glucose into starch, glycogen or cellulose, and amino acids into proteins.', 30),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'What is respiration?', 'An exothermic chemical reaction in all living cells that releases energy from glucose.', 1),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Give the word equation for aerobic respiration.', 'Glucose + oxygen → carbon dioxide + water (energy released).', 2),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Give the balanced symbol equation for aerobic respiration.', 'C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O.', 3),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Where does aerobic respiration take place?', 'Mainly in the mitochondria.', 4),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Give the word equation for anaerobic respiration in animals.', 'Glucose → lactic acid (energy released).', 5),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Give the word equation for anaerobic respiration in plants and yeast.', 'Glucose → ethanol + carbon dioxide (energy released). Also called fermentation.', 6),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Where does anaerobic respiration take place?', 'In the cytoplasm.', 7),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Why does anaerobic respiration release less energy than aerobic?', 'Glucose is only partially broken down; much energy remains in lactic acid or ethanol.', 8),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'What is ATP?', 'Adenosine triphosphate, the molecule that transfers energy released in respiration to cell processes.', 9),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Give three uses of energy from respiration.', 'Muscle contraction, active transport, synthesis of large molecules (e.g. proteins), keeping warm in mammals and birds.', 10),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Is respiration endothermic or exothermic?', 'Exothermic: it releases energy to the surroundings.', 11),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'When do human muscles respire anaerobically?', 'During vigorous exercise when oxygen cannot be supplied fast enough for aerobic respiration.', 12),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'What is oxygen debt?', 'The extra oxygen needed after exercise to break down lactic acid (oxidise it to CO₂ and water).', 13),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Why do breathing rate and heart rate stay high after exercise?', 'To supply extra oxygen to repay the oxygen debt and remove lactic acid and CO₂.', 14),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Why does lactic acid cause muscle fatigue?', 'It builds up in muscles, causing them to tire and contract less efficiently (cramp).', 15),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Give two uses of yeast fermentation.', 'Bread-making (CO₂ makes dough rise) and brewing beer and wine (ethanol produced).', 16),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Compare oxygen requirement of aerobic and anaerobic respiration.', 'Aerobic needs oxygen; anaerobic does not.', 17),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Compare products of aerobic and anaerobic respiration in animals.', 'Aerobic: CO₂ and water. Anaerobic: lactic acid only.', 18),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'What is metabolism?', 'The sum of all the chemical reactions in a cell or organism.', 19),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'What are carbohydrates built from?', 'Simple sugars such as glucose, joined into polymers like starch, glycogen or cellulose.', 20),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'What are lipids built from?', 'Glycerol and three fatty acids.', 21),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'What are proteins built from?', 'Amino acids joined in chains.', 22),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'PAG B6: How can you measure respiration rate in germinating peas?', 'Use a respirometer with soda lime to absorb CO₂; oxygen uptake moves a coloured liquid along a capillary; measure distance moved per minute.', 23),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Why is soda lime used in a respirometer?', 'It absorbs carbon dioxide, so movement of the liquid is due only to oxygen consumed.', 24),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Why are boiled (dead) peas used in a respirometer experiment?', 'As a control, showing any change is due to respiration by living peas.', 25),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'PAG B6: How could you investigate temperature and yeast respiration?', 'Yeast + glucose solution in water baths at different temperatures; count CO₂ bubbles or measure gas volume in a gas syringe per minute.', 26),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Calculate the rate of respiration if a bead moves 24 mm in 8 minutes.', 'Rate = 24 ÷ 8 = 3 mm per minute.', 27),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Why does yeast respiration rate drop at very high temperatures?', 'Enzymes controlling respiration denature, so the reaction slows or stops.', 28),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Exam trap: do plants respire only at night?', 'No. Plants respire all the time; in daylight photosynthesis rate usually exceeds respiration rate.', 29),
  ('Biology', 'OCR A', 'gcse', 'B1.3', 'Respiration', 'Why can anaerobic respiration only be used for short periods in humans?', 'It releases little energy and lactic acid builds up, causing fatigue.', 30),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'What is photosynthesis?', 'An endothermic process in which plants use light energy to make glucose from carbon dioxide and water.', 1),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Give the word equation for photosynthesis.', 'Carbon dioxide + water → glucose + oxygen (light energy, chlorophyll).', 2),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Give the balanced symbol equation for photosynthesis.', '6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂.', 3),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Where does photosynthesis occur?', 'In chloroplasts, which contain chlorophyll to absorb light.', 4),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Is photosynthesis endothermic or exothermic?', 'Endothermic: it takes in energy (light) from the surroundings.', 5),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'What are the two main stages of photosynthesis?', 'Light-dependent stage: water split to release oxygen using light energy. Then CO₂ combines with hydrogen to make glucose.', 6),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Why are plants described as producers?', 'They make their own food (glucose) by photosynthesis, providing biomass for food chains.', 7),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Name four uses of glucose in plants.', 'Respiration; converted to starch for storage; cellulose for cell walls; amino acids (with nitrates) for proteins; lipids for storage.', 8),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Why is glucose stored as starch?', 'Starch is insoluble, so it does not affect water potential (osmosis) and is compact.', 9),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'What is a limiting factor?', 'The factor in shortest supply that limits the rate of a process, e.g. light intensity, CO₂ concentration or temperature.', 10),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Describe the effect of light intensity on photosynthesis rate.', 'Rate increases as light intensity increases until another factor (e.g. CO₂ or temperature) becomes limiting and the graph plateaus.', 11),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Why does photosynthesis rate fall at high temperature?', 'Enzymes involved are denatured.', 12),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', '(Higher) How do you identify the limiting factor on a graph?', '(Higher) Where the line rises, the x-axis factor is limiting; where it plateaus, another factor is limiting (shown if a higher line exists for more CO₂/temperature).', 13),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'State the inverse square law for light intensity.', 'Light intensity ∝ 1 ÷ distance². Doubling the distance reduces intensity to a quarter.', 14),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', '(Higher) A lamp moves from 10 cm to 20 cm away. What happens to light intensity?', '(Higher) Intensity = 1/d²: 1/100 to 1/400, so it falls to a quarter.', 15),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Calculate relative light intensity at 25 cm using 1/d².', '1 ÷ 25² = 1 ÷ 625 = 0.0016 (arbitrary units).', 16),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'PAG B5: Describe how to investigate light intensity and pondweed.', 'Place pondweed in sodium hydrogencarbonate solution; vary lamp distance; count oxygen bubbles (or collect gas) per minute at each distance.', 17),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'PAG B5: Why is sodium hydrogencarbonate added to the water?', 'It supplies carbon dioxide so CO₂ is not a limiting factor.', 18),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'PAG B5: Why is a heat shield or LED used with the lamp?', 'To stop the lamp heating the water, so temperature stays a controlled variable.', 19),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Why is counting bubbles less accurate than using a gas syringe?', 'Bubbles vary in size and fast bubbles are hard to count; a syringe measures the actual volume.', 20),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'PAG B5: Name the variables in the pondweed experiment.', 'IV: light intensity (distance). DV: bubbles or volume of O₂ per minute. Controls: temperature, CO₂ concentration, same pondweed, time.', 21),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'How do you test a leaf for starch?', 'Boil in water (kill cells), boil in ethanol in a water bath (remove chlorophyll), rinse in warm water, add iodine; blue-black means starch.', 22),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Why is a variegated leaf used in photosynthesis experiments?', 'Only green parts contain chlorophyll; after starch testing only green areas turn blue-black, showing chlorophyll is needed.', 23),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Why must a plant be destarched before a starch test experiment?', 'Keep it in the dark for 48 hours so existing starch is used up; any starch found was made during the experiment.', 24),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'How do greenhouse growers increase crop yield?', 'Increase light, CO₂ (paraffin heaters) and temperature so these are not limiting, balanced against cost.', 25),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Why is the oxygen from photosynthesis important?', 'Released as a by-product; used by plants and animals for aerobic respiration.', 26),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'What is the compensation point?', 'The light intensity at which rate of photosynthesis equals rate of respiration, so there is no net gas exchange.', 27),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Exam trap: do plants take in CO₂ for energy?', 'No. CO₂ is a raw material for making glucose; energy comes from light.', 28),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'Why is the rate of photosynthesis a factor in food chains?', 'It determines how much biomass producers make, which is the energy source for all other organisms.', 29),
  ('Biology', 'OCR A', 'gcse', 'B1.4', 'Photosynthesis', 'How are leaves adapted for photosynthesis?', 'Broad, thin (large surface area, short diffusion distance), many chloroplasts in palisade layer, stomata for gas exchange, veins for water.', 30),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'What is diffusion?', 'Net movement of particles from a higher to a lower concentration, down a concentration gradient. Passive (no energy needed).', 1),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'What is osmosis?', 'Net diffusion of water molecules from a dilute solution to a more concentrated solution across a partially permeable membrane.', 2),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'What is active transport?', 'Movement of substances from a lower to a higher concentration against a gradient, using energy from respiration and carrier proteins.', 3),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Give an example of active transport in plants.', 'Root hair cells absorb mineral ions (e.g. nitrates) from dilute soil water.', 4),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Give an example of active transport in animals.', 'Absorption of glucose from the small intestine into the blood when gut concentration is low.', 5),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Give three factors that increase the rate of diffusion.', 'Steeper concentration gradient, higher temperature, larger surface area, shorter diffusion distance.', 6),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Why do root hair cells need many mitochondria?', 'To release energy by respiration for active transport of mineral ions.', 7),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'What happens to an animal cell in pure water?', 'Water enters by osmosis; the cell swells and may burst (lysis) as it has no cell wall.', 8),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'What happens to a plant cell in pure water?', 'Water enters by osmosis; the cell becomes turgid but the cell wall stops it bursting.', 9),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'What is plasmolysis?', 'In a concentrated solution, a plant cell loses water by osmosis and the membrane pulls away from the cell wall.', 10),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'What happens to red blood cells in a concentrated salt solution?', 'They lose water by osmosis and shrink (become crenated).', 11),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'PAG B8: Describe the potato osmosis practical.', 'Cut equal potato cylinders, blot and weigh; place in sucrose solutions of different concentrations for set time; blot and reweigh; calculate % change in mass.', 12),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Why calculate percentage change in mass in the potato practical?', 'Cylinders start at different masses, so percentage change allows fair comparison.', 13),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Calculate % change: potato from 2.50 g to 2.20 g.', '(2.20 − 2.50) ÷ 2.50 × 100 = −12%.', 14),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'How do you find the concentration of potato cell sap from a graph?', 'Plot % mass change against concentration; where the line crosses 0% change is the concentration equal to the cell sap.', 15),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Why are potato cylinders blotted before weighing?', 'To remove surface solution so only water absorbed into cells is measured.', 16),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'What is a stem cell?', 'An undifferentiated cell that can divide to produce more cells and differentiate into specialised cell types.', 17),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'What is differentiation?', 'The process by which a cell becomes specialised for a particular function.', 18),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Where are stem cells found in animals?', 'Embryos (can form any cell type) and adult tissues such as bone marrow (limited range of cells).', 19),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Where are stem cells found in plants?', 'Meristems, found at root and shoot tips; they can differentiate into any plant cell type throughout life.', 20),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Give a potential medical use of stem cells.', 'Replacing damaged cells, e.g. treating diabetes, paralysis or leukaemia (bone marrow transplants).', 21),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Give one ethical issue with embryonic stem cells.', 'Embryos are destroyed, which some believe is wrong as an embryo is a potential life.', 22),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Give one risk of stem cell therapy.', 'Cells could divide uncontrollably causing cancer, or carry viral infections, or be rejected.', 23),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'What is mitosis used for?', 'Growth, repair and asexual reproduction; produces two genetically identical diploid cells.', 24),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Describe the stages of the cell cycle.', 'Interphase: cell grows, organelles and DNA replicate. Mitosis: chromosomes pulled apart to each pole. Cytokinesis: cytoplasm and membrane divide.', 25),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'What happens to DNA before mitosis?', 'It is replicated so each chromosome forms two identical chromatids.', 26),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'How many cells does mitosis produce and are they identical?', 'Two daughter cells, genetically identical to each other and to the parent.', 27),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'What is cancer in terms of the cell cycle?', 'Uncontrolled cell division caused by mutations in genes controlling the cell cycle, forming a tumour.', 28),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Calculate: a cell divides every 20 minutes. How many cells from one after 2 hours?', '120 ÷ 20 = 6 divisions; 2⁶ = 64 cells.', 29),
  ('Biology', 'OCR A', 'gcse', 'B2.1', 'Supplying the Cell', 'Exam trap: is osmosis the movement of solute?', 'No. Osmosis is the movement of water only, across a partially permeable membrane.', 30),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'Why do multicellular organisms need exchange surfaces and transport systems?', 'They have a small surface area to volume ratio, so diffusion through the surface is too slow to supply inner cells.', 1),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'Calculate the SA:V ratio of a 2 cm cube.', 'SA = 6 × 2² = 24 cm²; V = 2³ = 8 cm³; ratio 24:8 = 3:1.', 2),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'What happens to SA:V ratio as size increases?', 'It decreases, because volume increases faster than surface area.', 3),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'Give four features of an efficient exchange surface.', 'Large surface area, thin (short diffusion distance), good blood supply (steep gradient), ventilated (gas exchange).', 4),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'How are alveoli adapted for gas exchange?', 'Huge surface area, walls one cell thick, moist, surrounded by capillaries, ventilated to maintain concentration gradients.', 5),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'How are villi adapted for absorption?', 'Large surface area with microvilli, thin wall, good blood supply via capillaries, lacteal for fat absorption.', 6),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'Name the three types of blood vessel.', 'Arteries, veins and capillaries.', 7),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'How are arteries adapted?', 'Thick muscular and elastic walls to withstand and maintain high pressure; narrow lumen. Carry blood away from the heart.', 8),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'How are veins adapted?', 'Thin walls, large lumen, valves to prevent backflow; carry low-pressure blood to the heart.', 9),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'How are capillaries adapted?', 'Walls one cell thick for short diffusion distance; very narrow; form networks close to cells.', 10),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'What does double circulation mean?', 'Blood passes through the heart twice per circuit: heart to lungs (pulmonary) and heart to body (systemic).', 11),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'Describe the path of blood through the heart.', 'Vena cava → right atrium → right ventricle → pulmonary artery → lungs → pulmonary vein → left atrium → left ventricle → aorta.', 12),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'Why is the left ventricle wall thicker than the right?', 'It must pump blood at high pressure all around the body; the right only pumps to the nearby lungs.', 13),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'What is the function of heart valves?', 'To prevent backflow of blood, ensuring it flows in one direction.', 14),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'What is the function of red blood cells?', 'Carry oxygen bound to haemoglobin; biconcave shape for large surface area and no nucleus for more space.', 15),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'What is the function of white blood cells?', 'Defend against pathogens by phagocytosis or producing antibodies and antitoxins.', 16),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'What is the function of platelets?', 'Cell fragments that help blood clot at wounds.', 17),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'What does plasma transport?', 'Dissolved CO₂, glucose, amino acids, urea, hormones, and heat; carries blood cells.', 18),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'What is the function of xylem?', 'Transports water and mineral ions from roots to leaves; made of dead cells with lignin, hollow tubes, one direction only.', 19),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'What is the function of phloem?', 'Transports dissolved sugars (sucrose) up and down the plant (translocation); living cells with sieve plates.', 20),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'What is transpiration?', 'Loss of water vapour from leaves by evaporation and diffusion through stomata, pulling water up the xylem.', 21),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'Give four factors that increase transpiration rate.', 'Higher light intensity, higher temperature, more air movement (wind), lower humidity.', 22),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'Why does high humidity reduce transpiration?', 'The concentration gradient of water vapour between leaf and air is smaller, so diffusion is slower.', 23),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'How do guard cells open stomata?', 'In light, guard cells take in water and become turgid, curving apart to open the stoma.', 24),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'PAG B6: How is a potometer used?', 'Measures water uptake: time how far an air bubble moves along a capillary tube; assume uptake equals transpiration.', 25),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'Why must a potometer shoot be cut underwater?', 'To prevent air entering the xylem, which would block water flow.', 26),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'Calculate the rate of water uptake: bubble moves 15 mm in 5 minutes.', '15 ÷ 5 = 3 mm/min.', 27),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'Calculate volume of water uptake: bubble moves 40 mm in a tube of cross-sectional area 0.5 mm².', 'Volume = distance × area = 40 × 0.5 = 20 mm³.', 28),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'Calculate cardiac output: heart rate 70 bpm, stroke volume 75 cm³.', 'Cardiac output = 70 × 75 = 5250 cm³/min.', 29),
  ('Biology', 'OCR A', 'gcse', 'B2.2', 'The Challenges of Size', 'Exam trap: do all arteries carry oxygenated blood?', 'No. The pulmonary artery carries deoxygenated blood to the lungs; the pulmonary vein carries oxygenated blood.', 30),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What does the nervous system allow organisms to do?', 'Detect stimuli and react quickly via electrical impulses, coordinating responses.', 1),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'Name the parts of the central nervous system.', 'Brain and spinal cord.', 2),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What is a receptor?', 'A cell that detects a stimulus (change in environment), e.g. light receptors in the eye.', 3),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What is an effector?', 'A muscle or gland that produces a response.', 4),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'Give the order of a nervous response.', 'Stimulus → receptor → sensory neurone → CNS (relay) → motor neurone → effector → response.', 5),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What does a sensory neurone do?', 'Carries impulses from receptors to the CNS.', 6),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What does a motor neurone do?', 'Carries impulses from the CNS to effectors.', 7),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What is the role of the myelin sheath?', 'Insulates the axon and speeds up transmission of impulses.', 8),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'How are neurones adapted?', 'Long axon to carry impulses far, dendrites to connect with many neurones, myelin sheath to speed transmission.', 9),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What is a synapse?', 'A tiny gap between two neurones.', 10),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'Describe how an impulse crosses a synapse.', 'Impulse triggers release of neurotransmitter, which diffuses across the gap and binds to receptors on the next neurone, triggering a new impulse.', 11),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What is a reflex action?', 'A rapid, automatic response to a stimulus that does not involve the conscious brain, protecting the body.', 12),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'Describe a reflex arc.', 'Receptor → sensory neurone → relay neurone in spinal cord → motor neurone → effector.', 13),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'Why are reflexes faster than conscious responses?', 'The pathway bypasses the conscious brain and involves few synapses.', 14),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'Give two examples of reflexes.', 'Pupil contracting in bright light; withdrawing hand from a hot object; knee jerk; blinking.', 15),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What does the cerebrum control?', 'Conscious thought, memory, language, intelligence and voluntary movement.', 16),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What does the cerebellum control?', 'Balance, posture and coordination of muscular movement.', 17),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What does the medulla control?', 'Unconscious activities such as heart rate and breathing rate.', 18),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'Why is the brain difficult to study and treat?', 'Complex and delicate, protected by the skull, damage to one area can affect others; drugs struggle to reach it.', 19),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'Name methods used to study the brain.', 'Studying patients with brain damage, electrically stimulating areas, MRI and fMRI scans.', 20),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What is the function of the cornea?', 'Transparent outer layer that refracts light into the eye.', 21),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What is the function of the iris?', 'Muscle that controls pupil size and so the amount of light entering.', 22),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What is the function of the retina?', 'Contains light-sensitive rod and cone receptor cells.', 23),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What is the role of the lens and ciliary muscles?', 'Ciliary muscles and suspensory ligaments change lens shape to focus light on the retina (accommodation).', 24),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'Describe accommodation for a near object.', 'Ciliary muscles contract, suspensory ligaments slacken, lens becomes thicker and refracts light more.', 25),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'Describe accommodation for a distant object.', 'Ciliary muscles relax, suspensory ligaments tighten, lens is pulled thin and refracts light less.', 26),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What is myopia and how is it corrected?', 'Short-sightedness: light focuses in front of the retina. Corrected with a concave (diverging) lens.', 27),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What is hyperopia and how is it corrected?', 'Long-sightedness: light focuses behind the retina. Corrected with a convex (converging) lens.', 28),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'PAG B6: How can you measure reaction time?', 'Ruler drop test: partner drops a ruler, catch it, record distance; convert to time using a table; repeat and find mean.', 29),
  ('Biology', 'OCR A', 'gcse', 'B3.1', 'Coordination — Nervous System', 'What is colour blindness caused by?', 'Cone cells in the retina that do not work properly, usually red-green; an inherited condition.', 30),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What is the endocrine system?', 'A system of glands that secrete hormones directly into the blood, which carry them to target organs.', 1),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What is a hormone?', 'A chemical messenger secreted by a gland and carried in the blood to target organs.', 2),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'Compare nervous and hormonal responses.', 'Nervous: electrical, very fast, short-lived, precise. Hormonal: chemical in blood, slower, longer-lasting, more widespread.', 3),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'Why is the pituitary gland called the master gland?', 'It secretes hormones (e.g. FSH, LH, TSH, ADH) that control other glands.', 4),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What does the thyroid gland produce?', 'Thyroxine, which controls the basal metabolic rate.', 5),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', '(Higher) How is thyroxine controlled by negative feedback?', '(Higher) Low thyroxine → pituitary releases TSH → thyroid releases more thyroxine; high thyroxine inhibits TSH release.', 6),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What does the adrenal gland produce?', 'Adrenaline, preparing the body for fight or flight.', 7),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What are the effects of adrenaline?', 'Increases heart rate and breathing rate, boosts blood glucose and oxygen to muscles, dilates pupils.', 8),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What does the pancreas produce?', 'Insulin and glucagon to control blood glucose concentration.', 9),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What do the ovaries produce?', 'Oestrogen (and progesterone); eggs.', 10),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What do the testes produce?', 'Testosterone, which controls sperm production and male secondary sexual characteristics.', 11),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What is the role of FSH in the menstrual cycle?', 'Causes an egg to mature in the ovary and stimulates oestrogen production.', 12),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What is the role of LH in the menstrual cycle?', 'Stimulates ovulation (release of the egg) around day 14.', 13),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What is the role of oestrogen in the menstrual cycle?', 'Causes the uterus lining to thicken; inhibits FSH and (Higher) stimulates LH release.', 14),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What is the role of progesterone in the menstrual cycle?', 'Maintains the uterus lining; inhibits FSH and LH.', 15),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What happens when progesterone levels fall?', 'The uterus lining breaks down and menstruation occurs.', 16),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'How does the combined contraceptive pill work?', 'Contains oestrogen and progesterone, which inhibit FSH so no eggs mature or are released.', 17),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'Name two non-hormonal methods of contraception.', 'Condoms, diaphragms (barrier methods), copper IUD, spermicides, abstinence, sterilisation.', 18),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'Give one advantage of barrier contraception over hormonal methods.', 'Condoms also protect against sexually transmitted infections; no hormonal side effects.', 19),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'How is hormone therapy used to treat infertility?', 'FSH and LH are given to stimulate eggs to mature and be released.', 20),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'Describe in vitro fertilisation (IVF).', 'FSH and LH given; eggs collected and fertilised by sperm in a lab; embryos grow, then one or two are inserted into the uterus.', 21),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'Give two disadvantages of IVF.', 'Low success rate, expensive, emotionally stressful, risk of multiple births.', 22),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What are plant hormones called and what do they do?', 'Plant growth regulators, e.g. auxins, gibberellins and ethene, controlling growth and responses.', 23),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What is phototropism?', 'Growth of a plant in response to light; shoots grow towards light (positive phototropism).', 24),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'What is gravitropism?', 'Growth in response to gravity; roots grow down (positive), shoots grow up (negative).', 25),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'How does auxin cause shoots to bend towards light?', 'Auxin moves to the shaded side, causing cells there to elongate more, so the shoot bends towards light.', 26),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'Why do roots grow downwards?', 'Auxin collects on the lower side; in roots it inhibits elongation, so the upper side grows more and the root bends down.', 27),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', '(Higher) Give uses of auxins in agriculture.', '(Higher) Selective weedkillers, rooting powder for cuttings, promoting fruit growth.', 28),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', '(Higher) Give uses of gibberellins and ethene.', '(Higher) Gibberellins: end seed dormancy, promote flowering, make seedless fruit. Ethene: controls fruit ripening during transport.', 29),
  ('Biology', 'OCR A', 'gcse', 'B3.2', 'Coordination — Endocrine System', 'PAG B6: How can you investigate phototropism in seedlings?', 'Grow cress or oat seedlings with light from one side, all directions, or in darkness; measure angle of bending or growth after days.', 30),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'What is homeostasis?', 'Maintaining a constant internal environment despite internal and external changes.', 1),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'Name three things controlled by homeostasis.', 'Body temperature, blood glucose concentration and water content (water potential) of the blood.', 2),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'What is negative feedback?', 'When a change from the set point is detected and a response reverses the change, returning conditions to normal.', 3),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'What are the components of a control system?', 'Receptors detect change, coordination centre (brain, spinal cord, pancreas) processes it, effectors bring about a response.', 4),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'Why is homeostasis important for enzymes?', 'Enzymes need a constant temperature and pH to work at optimum rates and not denature.', 5),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'Where is body temperature monitored?', 'The thermoregulatory centre in the hypothalamus, and temperature receptors in the skin.', 6),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'How does the body respond when too hot?', 'Sweating (evaporation cools), vasodilation of skin arterioles (more heat lost by radiation), hairs lie flat.', 7),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'How does the body respond when too cold?', 'Shivering (respiration releases heat), vasoconstriction (less blood to skin), hairs raise to trap air.', 8),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'Exam trap: do blood vessels move closer to the skin in vasodilation?', 'No. Arterioles widen so more blood flows through skin capillaries; vessels do not move.', 9),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'What happens when blood glucose concentration is too high?', 'The pancreas releases insulin; glucose moves into cells and the liver and muscles convert it to glycogen.', 10),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', '(Higher) What happens when blood glucose concentration is too low?', '(Higher) The pancreas releases glucagon, which causes the liver to convert glycogen back into glucose.', 11),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'What is type 1 diabetes?', 'The pancreas produces little or no insulin; treated with insulin injections, diet and exercise.', 12),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'What is type 2 diabetes?', 'Body cells stop responding to insulin (or too little is made); linked to obesity; treated with diet, exercise and drugs.', 13),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'Give a risk factor for type 2 diabetes.', 'Obesity, poor diet, lack of exercise, age, family history.', 14),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'What is osmoregulation?', 'Controlling the water content (water potential) of the body.', 15),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'What do the kidneys do?', 'Filter the blood, reabsorb useful substances and water, and remove urea, excess water and ions as urine.', 16),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'Describe how a nephron makes urine.', 'Ultrafiltration in Bowman''s capsule; selective reabsorption of glucose, some ions and water; urea and excess water pass to the bladder.', 17),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'What is filtered out of blood in the Bowman''s capsule?', 'Small molecules: water, glucose, ions and urea. Proteins and blood cells are too large and stay in the blood.', 18),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'Why is there no glucose in the urine of a healthy person?', 'All glucose is selectively reabsorbed into the blood by active transport in the tubule.', 19),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'What is ADH and where is it released from?', 'Anti-diuretic hormone, released by the pituitary gland when blood is too concentrated.', 20),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', '(Higher) How does ADH control water content?', '(Higher) ADH makes collecting duct walls more permeable, so more water is reabsorbed into the blood, producing small volumes of concentrated urine.', 21),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'What happens to urine after drinking lots of water?', 'Less ADH is released, less water reabsorbed, so a large volume of dilute urine is produced.', 22),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'Why does exercise in heat produce concentrated urine?', 'Water is lost in sweat; blood becomes concentrated; more ADH is released and more water is reabsorbed.', 23),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'How is urea formed?', 'In the liver, excess amino acids are deaminated, producing ammonia which is converted to urea.', 24),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'Give two treatments for kidney failure.', 'Dialysis and kidney transplant.', 25),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'How does dialysis work?', 'Blood flows alongside dialysis fluid across a partially permeable membrane; urea and excess ions diffuse out; fluid has normal glucose and ion levels.', 26),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'Why does dialysis fluid contain glucose at blood concentration?', 'So there is no concentration gradient and glucose is not lost from the blood.', 27),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'Give one advantage of a kidney transplant over dialysis.', 'Long-term solution, more freedom, no dietary restrictions; cheaper in the long run.', 28),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'Give one disadvantage of a kidney transplant.', 'Shortage of donors, risk of rejection, need lifelong immunosuppressant drugs.', 29),
  ('Biology', 'OCR A', 'gcse', 'B3.3', 'Maintaining Internal Environments', 'Interpret: blood glucose rises after a meal then falls within 2 hours. Why?', 'Glucose absorbed from digestion raises levels; insulin is released, cells take up glucose and liver stores it as glycogen.', 30),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'What is an ecosystem?', 'The interaction of a community of living organisms with the non-living (abiotic) parts of their environment.', 1),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'What is a community?', 'All the populations of different species living in a habitat.', 2),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'What is a population?', 'All the organisms of one species living in a habitat.', 3),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Give three abiotic factors.', 'Light intensity, temperature, moisture, soil pH and mineral content, wind, CO₂ and O₂ levels.', 4),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Give three biotic factors.', 'Food availability, new predators, new pathogens, competition between species.', 5),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'What do plants compete for?', 'Light, space, water and mineral ions.', 6),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'What do animals compete for?', 'Food, mates and territory.', 7),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'What is interdependence?', 'Species depend on each other for food, shelter, pollination, seed dispersal, so changing one population affects others.', 8),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Describe predator–prey cycles.', 'Prey numbers rise, so predators increase; prey then fall, so predators fall; the predator peak lags behind the prey peak.', 9),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'What is parasitism?', 'A relationship where the parasite benefits and the host is harmed, e.g. tapeworms, fleas.', 10),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'What is mutualism?', 'A relationship where both species benefit, e.g. bees and flowers, nitrogen-fixing bacteria in legume root nodules.', 11),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'What is a producer?', 'An organism that makes its own food by photosynthesis, at the start of a food chain.', 12),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'What do arrows in a food chain represent?', 'The direction of energy (biomass) transfer, from the organism eaten to the eater.', 13),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'What is a trophic level?', 'The position of an organism in a food chain, e.g. producer (1), primary consumer (2).', 14),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Why do food chains rarely have more than five trophic levels?', 'Energy is lost at each level, so too little remains to support further levels.', 15),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Give three ways biomass is lost between trophic levels.', 'Not all of an organism is eaten; some is egested (faeces); energy used in respiration and lost as heat; excretion (urea).', 16),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Calculate efficiency: 1000 kJ in grass, 100 kJ in rabbits.', 'Efficiency = 100 ÷ 1000 × 100 = 10%.', 17),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Why are pyramids of biomass always pyramid-shaped?', 'Biomass decreases at each trophic level because of losses in respiration, waste and uneaten parts.', 18),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Describe the carbon cycle.', 'CO₂ removed by photosynthesis; returned by respiration of plants, animals and decomposers, and combustion; carbon passes through food chains.', 19),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'What is the role of decomposers in nutrient cycles?', 'Bacteria and fungi break down dead organisms and waste, returning CO₂ by respiration and mineral ions to the soil.', 20),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Describe the water cycle.', 'Evaporation and transpiration form water vapour; it condenses into clouds; precipitation returns water; it runs off or percolates into ground.', 21),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Describe the nitrogen cycle.', 'Nitrogen-fixing bacteria convert N₂ to nitrogen compounds; decomposers make ammonia; nitrifying bacteria convert to nitrates; denitrifying bacteria return N₂.', 22),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Why do plants need nitrates?', 'To make amino acids and proteins for growth.', 23),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Give three factors affecting decomposition rate.', 'Temperature, water availability, oxygen availability, number of decomposers.', 24),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Why does decay slow in waterlogged soil?', 'There is little oxygen, so aerobic respiration by decomposers is reduced.', 25),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'PAG B3: How do you estimate population size using quadrats?', 'Place quadrats at random coordinates, count organisms, find mean per quadrat, then multiply by (total area ÷ quadrat area).', 26),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Estimate: mean 6 daisies per 0.25 m² quadrat in a 100 m² field.', '6 × (100 ÷ 0.25) = 6 × 400 = 2400 daisies.', 27),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'PAG B3: How is a transect used?', 'Lay a tape across a habitat (e.g. shade to light); place quadrats at regular intervals; record abundance and abiotic factors to find a correlation.', 28),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'Why must quadrats be placed randomly?', 'To avoid bias so the sample is representative of the whole area.', 29),
  ('Biology', 'OCR A', 'gcse', 'B4.1', 'Ecosystems', 'What is capture–recapture and how is population estimated?', 'Mark animals, release, recapture later. Population = (number in 1st sample × number in 2nd sample) ÷ number marked in 2nd sample.', 30),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is a genotype?', 'The combination of alleles an organism has for a gene, e.g. Bb.', 1),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is a phenotype?', 'The observable characteristics of an organism, resulting from genotype and environment.', 2),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is an allele?', 'A different version of the same gene.', 3),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What does dominant mean?', 'An allele that is expressed if only one copy is present (shown with a capital letter).', 4),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What does recessive mean?', 'An allele only expressed if two copies are present, i.e. homozygous recessive.', 5),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is homozygous?', 'Having two identical alleles for a gene, e.g. BB or bb.', 6),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is heterozygous?', 'Having two different alleles for a gene, e.g. Bb.', 7),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is a mutation?', 'A change in the DNA base sequence; most have no effect, some alter a protein''s shape and function.', 8),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', '(Higher) How can a mutation in a non-coding region affect phenotype?', '(Higher) It can change how genes are switched on or off (gene expression), altering how much protein is made.', 9),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is sexual reproduction?', 'Fusion of male and female gametes, producing genetically varied offspring.', 10),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is asexual reproduction?', 'One parent, no gametes, mitosis only; offspring are genetically identical clones.', 11),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is meiosis?', 'Cell division producing four genetically different haploid gametes, each with half the chromosome number.', 12),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'How many chromosomes are in a human gamete and body cell?', 'Gamete: 23 (haploid). Body cell: 46, i.e. 23 pairs (diploid).', 13),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'Why is meiosis important?', 'Halves chromosome number so fertilisation restores the diploid number, and creates genetic variation.', 14),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What are sex chromosomes in males and females?', 'Females XX, males XY.', 15),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is the probability that a baby is a boy?', '50% (0.5): mother gives X; father gives X or Y with equal probability.', 16),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'Bb × Bb: what ratio of phenotypes is expected?', '3 dominant : 1 recessive (75% dominant, 25% recessive).', 17),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'Bb × bb: what proportion of offspring show the recessive phenotype?', '50% (1:1 ratio; offspring Bb and bb).', 18),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'Two heterozygous parents for cystic fibrosis (Ff). Probability of an affected child?', '1 in 4 (25%), genotype ff.', 19),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is a carrier?', 'A heterozygous person carrying one recessive allele for a disorder but not showing the symptoms.', 20),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is polydactyly?', 'Inherited disorder causing extra fingers or toes; caused by a dominant allele.', 21),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is cystic fibrosis?', 'A recessive inherited disorder of cell membranes causing thick mucus in lungs and pancreas.', 22),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'Why do most characteristics not follow simple single-gene inheritance?', 'Most are controlled by multiple genes interacting, plus environmental influence, e.g. height.', 23),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'Who was Gregor Mendel?', 'A monk who bred pea plants and showed characteristics are inherited as separate units (now called genes) that can be dominant or recessive.', 24),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'Why was Mendel''s work not accepted at first?', 'Chromosomes, genes and DNA had not been discovered, so there was no mechanism to explain his results.', 25),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What are the two types of variation?', 'Genetic (inherited) and environmental; most characteristics are a mix of both.', 26),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is continuous variation?', 'Variation with a range of values, e.g. height; usually multiple genes plus environment; shown on a histogram.', 27),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'What is discontinuous variation?', 'Variation in distinct categories, e.g. blood group; often single gene; shown on a bar chart.', 28),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'Give a role of the Human Genome Project.', 'Mapped all human genes; helps identify disease-linked genes, develop treatments and understand ancestry.', 29),
  ('Biology', 'OCR A', 'gcse', 'B5.1', 'Inheritance', 'Exam trap: does dominant mean more common?', 'No. Dominant only means it is expressed in heterozygotes; a dominant allele can be rare (e.g. polydactyly).', 30),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'What is evolution?', 'A change in inherited characteristics of a population over time through natural selection, which may lead to new species.', 1),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'Describe natural selection.', 'Variation exists; individuals with advantageous traits survive and reproduce more; they pass alleles on; allele becomes more common over generations.', 2),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'Why is variation essential for natural selection?', 'Without differences, no individuals are better adapted to survive, so selection cannot act.', 3),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'What causes genetic variation in a population?', 'Mutations, and sexual reproduction (meiosis and random fertilisation).', 4),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'How do antibiotic-resistant bacteria evolve?', 'Mutation gives resistance; antibiotic kills non-resistant bacteria; resistant ones survive and reproduce, so the population becomes resistant.', 5),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'Why do bacteria evolve quickly?', 'They reproduce very rapidly, so many generations occur in a short time.', 6),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'How can we reduce antibiotic resistance?', 'Only prescribe when needed, not for viral infections; complete the course; restrict use in farming.', 7),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'Exam trap: do bacteria become resistant because of the antibiotic?', 'No. Resistance arises by random mutation; the antibiotic only selects for already-resistant bacteria.', 8),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'What is a species?', 'A group of organisms that can interbreed to produce fertile offspring.', 9),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'Describe how a new species forms (speciation).', 'Populations become isolated; different mutations and selection pressures act; eventually they can no longer interbreed to produce fertile offspring.', 10),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'Who proposed the theory of evolution by natural selection?', 'Charles Darwin, published in On the Origin of Species (1859); Alfred Russel Wallace developed similar ideas.', 11),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'Why was Darwin''s theory controversial?', 'It challenged the belief God created all life; there was little evidence at the time; inheritance mechanisms were unknown.', 12),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'What was Lamarck''s idea?', 'Characteristics acquired during a lifetime are passed on to offspring. Now rejected as most acquired changes are not inherited.', 13),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'What evidence supports evolution?', 'Fossils, antibiotic resistance in bacteria, DNA and genome comparisons.', 14),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'How are fossils formed?', 'Hard parts replaced by minerals, preserved in conditions lacking decay (ice, amber, peat), or as traces in rock.', 15),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'Why is the fossil record incomplete?', 'Soft-bodied organisms rarely fossilise, conditions are seldom right, and many fossils destroyed by geological activity.', 16),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'How does DNA evidence support evolution?', 'Closely related species share more similar DNA base sequences, showing common ancestry.', 17),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'What is classification?', 'Organising living things into groups based on shared characteristics.', 18),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'List the Linnaean classification hierarchy.', 'Kingdom, phylum, class, order, family, genus, species.', 19),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'What is the binomial naming system?', 'Two-part Latin name: genus then species, e.g. Homo sapiens.', 20),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'What is the three-domain system?', 'Proposed by Woese: Archaea, Bacteria and Eukaryota, based on chemical (RNA) analysis.', 21),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'Why has classification changed over time?', 'New evidence from microscopes, biochemistry and DNA sequencing reveals relationships that appearance alone missed.', 22),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'What is an evolutionary tree?', 'A diagram showing how species are related and evolved from common ancestors.', 23),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'What is selective breeding?', 'Humans choose individuals with desired traits to breed over many generations (artificial selection).', 24),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'Give one problem with selective breeding.', 'Inbreeding reduces the gene pool, increasing inherited disease risk and vulnerability to new diseases.', 25),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'What is extinction?', 'When no individuals of a species remain alive.', 26),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'Give three causes of extinction.', 'New predators, new diseases, more successful competitors, environmental change, habitat destruction.', 27),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'What is an adaptation?', 'A feature that helps an organism survive in its environment, resulting from natural selection.', 28),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'Exam trap: does an animal adapt because it needs to?', 'No. Individuals do not change; populations evolve because those with existing useful alleles survive and reproduce.', 29),
  ('Biology', 'OCR A', 'gcse', 'B5.2', 'Natural Selection & Evolution', 'What is a gene pool?', 'All the alleles present in a population.', 30),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'What is biodiversity?', 'The variety of all the different species of organisms on Earth, or within an ecosystem.', 1),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'Why is high biodiversity important?', 'Makes ecosystems stable, reduces dependence on one species, provides food, medicines and materials.', 2),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'Give four human activities that reduce biodiversity.', 'Deforestation, pollution, overfishing, building, agriculture (monocultures), introducing non-native species.', 3),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'Why is the human population growth a problem for the environment?', 'More land, food and resources used, and more waste and pollution produced.', 4),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'Name three types of pollution.', 'Air (smoke, acid gases), water (sewage, fertilisers, toxic chemicals), land (landfill, pesticides).', 5),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'How does fertiliser run-off cause eutrophication?', 'Nitrates cause algal bloom, blocking light; plants die; decomposers increase and use up oxygen; fish and animals die.', 6),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'What are indicator species?', 'Organisms whose presence or absence indicates pollution levels, e.g. lichens (air), mayfly larvae (clean water).', 7),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'What does the presence of many lichens indicate?', 'Clean air with low sulfur dioxide levels.', 8),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'What do bloodworms or sludgeworms indicate?', 'Polluted water with low oxygen.', 9),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'How does deforestation increase atmospheric CO₂?', 'Fewer trees to absorb CO₂ in photosynthesis, and burning or decay of trees releases CO₂.', 10),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'What are the main greenhouse gases?', 'Carbon dioxide and methane (also water vapour and nitrous oxide).', 11),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'Give effects of global warming on biodiversity.', 'Habitat loss, species migrating, changes in distribution, sea level rise, extinctions.', 12),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'Why is peat bog destruction harmful?', 'Burning or decay of peat releases CO₂; it destroys habitats and reduces biodiversity.', 13),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'What is a non-indigenous species?', 'A species introduced to an area where it does not naturally live; can outcompete native species, e.g. grey squirrels.', 14),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'How can biodiversity be maintained?', 'Breeding programmes, protecting habitats, reintroducing hedgerows, reducing deforestation, recycling, seed banks.', 15),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'What is a seed bank?', 'A store of seeds from many plant species, conserving genetic diversity in case species become extinct.', 16),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'Give one challenge of conservation.', 'Conflict with economic needs (e.g. farming, jobs), cost, monitoring, gaining international cooperation.', 17),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'What is ecotourism?', 'Tourism that funds conservation and benefits local people while having minimal environmental impact.', 18),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'How are captive breeding programmes useful?', 'Increase numbers of endangered species, maintain genetic diversity, and can reintroduce animals to the wild.', 19),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'Why do hedgerows increase biodiversity?', 'Provide habitats, food and corridors for many species in farmland otherwise dominated by monocultures.', 20),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'What is a monoculture and why does it reduce biodiversity?', 'Large area growing one crop; few habitats and food sources for other species.', 21),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'How do you sample to compare biodiversity in two areas?', 'Random quadrat sampling in each area; count species and numbers; compare species richness.', 22),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'Why is a large sample size used when monitoring the environment?', 'Gives more representative, reliable results and reduces effect of anomalies.', 23),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'What is acid rain caused by?', 'Sulfur dioxide and nitrogen oxides from burning fossil fuels dissolving in rainwater.', 24),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'What are the effects of acid rain?', 'Kills trees and aquatic life, acidifies lakes and soil, damages buildings.', 25),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'How can untreated sewage harm rivers?', 'Bacteria decompose it using oxygen, so oxygen levels fall and aquatic organisms die.', 26),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'Why is landfill a problem?', 'Uses land, destroys habitats, can leak toxic chemicals and releases methane.', 27),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'What is sustainable development?', 'Meeting the needs of present generations without harming the ability of future generations to meet theirs.', 28),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'Calculate population growth: 7.8 billion rising to 8.1 billion.', '% increase = (8.1 − 7.8) ÷ 7.8 × 100 ≈ 3.8%.', 29),
  ('Biology', 'OCR A', 'gcse', 'B6.1', 'Monitoring & Maintaining the Environment', 'Exam trap: is global warming caused by the ozone hole?', 'No. Global warming is caused by greenhouse gases trapping heat; ozone depletion is a separate issue.', 30),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'What is food security?', 'Having enough affordable, safe and nutritious food for everyone.', 1),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Give four threats to food security.', 'Growing population, changing diets, new pests and pathogens, climate change, conflicts, cost of farming inputs.', 2),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Why do changing diets threaten food security?', 'Wealthier populations eat more meat, which requires much more land and crops to produce than plant food.', 3),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Why is eating plants more efficient than eating meat?', 'Energy is lost at each trophic level, so eating producers gives more energy from the same land.', 4),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'How does intensive farming increase yield?', 'Fertilisers, pesticides, herbicides, keeping animals indoors to reduce movement and heat loss.', 5),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Give two drawbacks of intensive animal farming.', 'Ethical concerns about welfare, disease spreads quickly, antibiotic overuse, waste pollution.', 6),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'What is hydroponics?', 'Growing plants in nutrient solution instead of soil, controlling mineral supply and avoiding soil pests.', 7),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'What is biological control?', 'Using a natural predator or parasite to control a pest, e.g. ladybirds eating aphids.', 8),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Give one advantage and one disadvantage of biological control.', 'Advantage: no chemicals, long lasting. Disadvantage: control species may become a pest itself or harm other species.', 9),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'What is organic farming?', 'Farming without artificial fertilisers or pesticides, using manure, crop rotation and biological control.', 10),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'What is a genetically modified (GM) organism?', 'An organism whose genome has been altered by inserting a gene from another organism.', 11),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Give examples of GM crops.', 'Pest-resistant crops, herbicide-resistant crops, Golden Rice with vitamin A precursor.', 12),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Give two concerns about GM crops.', 'Effects on wild populations and insects, genes spreading to wild plants, unknown long-term health effects.', 13),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Describe the main stages of genetic engineering.', 'Cut out the gene with restriction enzymes; insert into a vector (plasmid or virus) with ligase; insert into host cell; select modified cells.', 14),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', '(Higher) What are sticky ends?', '(Higher) Short single-stranded overhangs left by restriction enzymes, allowing the gene and plasmid to join by complementary base pairing.', 15),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', '(Higher) What is the role of DNA ligase?', '(Higher) It joins the sugar-phosphate backbones of the gene and vector DNA together.', 16),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'How are bacteria used to make insulin?', 'The human insulin gene is inserted into a bacterial plasmid; bacteria are grown in fermenters and produce insulin.', 17),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'How can selective breeding improve food supply?', 'Breeding for high yield, disease resistance or faster growth over many generations.', 18),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'What are biofuels?', 'Fuels made from biomass, e.g. ethanol from fermented sugar cane, reducing fossil fuel use.', 19),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Why might biofuels threaten food security?', 'Land used to grow biofuel crops cannot be used for food.', 20),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'What is mycoprotein?', 'A protein-rich food made from the fungus Fusarium grown in fermenters, used as a meat substitute.', 21),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'How do fishing quotas help sustainable food production?', 'They limit catches so fish stocks can recover and breed.', 22),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'How does net mesh size help fish stocks?', 'Larger mesh lets young fish escape so they can reach breeding age.', 23),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Why do farmers use crop rotation?', 'Different crops use different nutrients; legumes restore nitrates; reduces pest build-up.', 24),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Why are fertilisers added to soil?', 'Replace mineral ions (nitrates, phosphates, potassium) removed by crops, increasing growth and yield.', 25),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'What do herbicides and pesticides do?', 'Herbicides kill weeds (reducing competition); pesticides kill insects and pests that damage crops.', 26),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Give one problem with pesticides.', 'Can kill non-target species and accumulate in food chains (bioaccumulation), harming top predators.', 27),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'What is the role of gene technology in disease-resistant crops?', 'Inserting resistance genes reduces crop losses and the need for pesticides.', 28),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Calculate yield increase from 4 to 5 tonnes per hectare as a percentage.', '(5 − 4) ÷ 4 × 100 = 25% increase.', 29),
  ('Biology', 'OCR A', 'gcse', 'B6.2', 'Feeding the Human Race', 'Exam trap: does GM mean the same as selective breeding?', 'No. Selective breeding uses existing variation over generations; GM inserts specific genes directly, even between species.', 30),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'What is health?', 'A state of complete physical, mental and social well-being, not just absence of disease.', 1),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'What is a communicable disease?', 'An infectious disease caused by pathogens that can spread between organisms.', 2),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'What is a non-communicable disease?', 'A disease that cannot be transmitted, e.g. heart disease, cancer, diabetes.', 3),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Name the four types of pathogen.', 'Bacteria, viruses, fungi and protists.', 4),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'How are pathogens spread?', 'Air (droplets), water, food, direct contact, body fluids, vectors (e.g. mosquitoes).', 5),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Describe measles.', 'Viral disease spread by droplets; fever and red rash; can be fatal; prevented by vaccination (MMR).', 6),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Describe HIV/AIDS.', 'Virus spread by sexual contact and body fluids; attacks immune cells leading to AIDS; controlled with antiretroviral drugs.', 7),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Describe malaria.', 'Caused by a protist spread by mosquito vectors; causes recurring fever; prevented by nets, insecticides and antimalarial drugs.', 8),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Describe tuberculosis.', 'Bacterial disease spread by droplets; damages lungs; treated with antibiotics; prevented by BCG vaccine.', 9),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Give a plant disease and its cause.', 'Tobacco mosaic virus (virus, mosaic leaf discolouration), ash dieback (fungus), crown gall (bacterium).', 10),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'How do plants defend against pathogens physically?', 'Waxy cuticle, cellulose cell walls, layers of dead bark cells.', 11),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'How do plants defend against pathogens chemically?', 'Antimicrobial substances and poisons that deter herbivores and kill pathogens.', 12),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'How can plant diseases be detected?', 'Observation of symptoms, lab testing, DNA analysis, monoclonal antibody testing kits.', 13),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Give three non-specific human defences.', 'Skin barrier, mucus and cilia in airways, stomach acid, lysozyme in tears, blood clotting.', 14),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'How do phagocytes destroy pathogens?', 'They engulf and digest pathogens (phagocytosis).', 15),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'How do lymphocytes destroy pathogens?', 'They produce antibodies specific to the pathogen''s antigens, and antitoxins that neutralise toxins.', 16),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'What are memory cells?', 'Lymphocytes that remain after infection and produce antibodies rapidly upon reinfection, giving immunity.', 17),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'How does vaccination work?', 'Dead or weakened pathogen (antigens) is injected; lymphocytes make antibodies and memory cells, so a second exposure triggers a fast response.', 18),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'What is herd immunity?', 'When a large proportion is vaccinated, the spread of the pathogen is reduced, protecting unvaccinated people.', 19),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Why don''t antibiotics work against viruses?', 'Viruses live inside host cells and lack the structures antibiotics target.', 20),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Describe the stages of drug testing.', 'Preclinical testing on cells, tissues and animals; then clinical trials on healthy volunteers (low doses), then patients; double-blind with placebo.', 21),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'What is a double-blind trial?', 'Neither patients nor doctors know who receives the drug or placebo, removing bias.', 22),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'PAG B7: How do you test the effect of antiseptics on bacteria?', 'Spread bacteria on agar, add paper discs soaked in antiseptics, incubate at 25 °C, measure clear zones of inhibition.', 23),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'PAG B7: Give three aseptic techniques.', 'Sterilise loop in a Bunsen flame, flame bottle necks, tape lid (not sealed), work near a flame, sterilise plates beforehand.', 24),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Why are cultures incubated at 25 °C in schools?', 'Reduces the chance of growing human pathogens that grow best at 37 °C.', 25),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Calculate the area of a clear zone with radius 6 mm.', 'Area = πr² = 3.14 × 6² ≈ 113 mm².', 26),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Calculate bacteria after 3 hours if one cell divides every 30 minutes.', '180 ÷ 30 = 6 divisions; 2⁶ = 64 bacteria.', 27),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Give risk factors for cardiovascular disease.', 'Smoking, high-fat diet, obesity, lack of exercise, high blood pressure, high cholesterol.', 28),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'Give treatments for cardiovascular disease.', 'Lifestyle change, statins (lower cholesterol), stents, bypass surgery, heart transplant.', 29),
  ('Biology', 'OCR A', 'gcse', 'B6.3', 'Monitoring & Maintaining Health', 'What are monoclonal antibodies used for?', 'Identical antibodies targeting one antigen; used in pregnancy tests, diagnosing disease and targeting cancer cells.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Biology' AND exam_board = 'OCR A' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
